-- Local-only, additive private DC tracker. 0004 and 0010-0013 remain reserved.
-- Private schema only; source configuration and transport are independently gated.
-- Each scope is an immutable source snapshot; business IDs persist across observations.
-- All source-derived rows cascade from research_observations through the existing bounded purge.
CREATE TABLE dc_entities ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), entity_id TEXT NOT NULL, name_ja TEXT NOT NULL, corporate_number TEXT CHECK(corporate_number IS NULL OR (length(corporate_number)=13 AND corporate_number NOT GLOB '*[^0-9]*')), PRIMARY KEY(obs_id,entity_id) );
CREATE INDEX dc_entities_run ON dc_entities(run_id);
CREATE TRIGGER dc_entities_immutable BEFORE UPDATE ON dc_entities BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_entities_retention BEFORE DELETE ON dc_entities WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_projects ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), project_id TEXT NOT NULL, name_ja TEXT NOT NULL, operator_entity_id TEXT, country TEXT, prefecture TEXT, tracked_since TEXT NOT NULL, tracking_status TEXT NOT NULL CHECK(tracking_status IN ('active','paused')), PRIMARY KEY(obs_id,project_id), FOREIGN KEY(obs_id,operator_entity_id) REFERENCES dc_entities(obs_id,entity_id) ON DELETE CASCADE );
CREATE INDEX dc_projects_run ON dc_projects(run_id);
CREATE TRIGGER dc_projects_immutable BEFORE UPDATE ON dc_projects BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_projects_retention BEFORE DELETE ON dc_projects WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_sites ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), site_id TEXT NOT NULL, project_id TEXT NOT NULL, name TEXT NOT NULL, region TEXT, location_evidence_ref TEXT, PRIMARY KEY(obs_id,site_id), FOREIGN KEY(obs_id,project_id) REFERENCES dc_projects(obs_id,project_id) ON DELETE CASCADE );
CREATE INDEX dc_sites_run ON dc_sites(run_id);
CREATE TRIGGER dc_sites_immutable BEFORE UPDATE ON dc_sites BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_sites_retention BEFORE DELETE ON dc_sites WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_phases ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), phase_id TEXT NOT NULL, site_id TEXT NOT NULL, phase_label TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','land','permit','grid_connection','power_application','power_contracted','permitted','construction','energized','facility_handover','it_installed','it_operational','paused','cancelled','unknown')), planned_service_date TEXT, actual_service_date TEXT, PRIMARY KEY(obs_id,phase_id), FOREIGN KEY(obs_id,site_id) REFERENCES dc_sites(obs_id,site_id) ON DELETE CASCADE );
CREATE INDEX dc_phases_run ON dc_phases(run_id);
CREATE TRIGGER dc_phases_immutable BEFORE UPDATE ON dc_phases BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_phases_retention BEFORE DELETE ON dc_phases WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_observations ( obs_id TEXT PRIMARY KEY REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), project_id TEXT NOT NULL, site_id TEXT, phase_id TEXT, field TEXT NOT NULL CHECK(field IN ('disclosure','status','planned_service_date','actual_service_date','planned_mw','contracted_mw','energized_mw','it_operational_mw','financing')), scope TEXT NOT NULL CHECK(scope IN ('project','site','phase')), scope_id TEXT NOT NULL, value_text TEXT, value_decimal TEXT, unit TEXT CHECK(unit IS NULL OR unit='MW'), as_of_date TEXT NOT NULL, source_id TEXT NOT NULL, source_url TEXT NOT NULL, source_published_at TEXT, fetched_at TEXT NOT NULL, evidence_sha256 TEXT NOT NULL CHECK(length(evidence_sha256)=64), evidence_level TEXT NOT NULL CHECK(evidence_level IN ('primary_disclosure','official_registry')), basis TEXT NOT NULL CHECK(basis IN ('announced','contracted','official_operational_report')), source_quote TEXT CHECK((field='disclosure' AND source_quote IS NULL) OR (source_quote IS NOT NULL AND length(trim(source_quote)) BETWEEN 1 AND 500)), status TEXT NOT NULL CHECK(status='draft'), drafted_by TEXT NOT NULL CHECK(drafted_by IN ('deterministic','ai_codex','ai_claude','kaz')), FOREIGN KEY(obs_id,project_id) REFERENCES dc_projects(obs_id,project_id) ON DELETE CASCADE, FOREIGN KEY(obs_id,site_id) REFERENCES dc_sites(obs_id,site_id) ON DELETE CASCADE, FOREIGN KEY(obs_id,phase_id) REFERENCES dc_phases(obs_id,phase_id) ON DELETE CASCADE, CHECK((field IN ('planned_mw','contracted_mw','energized_mw','it_operational_mw') AND value_decimal IS NOT NULL AND value_text IS NULL AND unit IS 'MW') OR (field NOT IN ('planned_mw','contracted_mw','energized_mw','it_operational_mw') AND value_decimal IS NULL AND unit IS NULL)) );
CREATE INDEX dc_observations_run ON dc_observations(run_id);
CREATE TRIGGER dc_observations_immutable BEFORE UPDATE ON dc_observations BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_observations_retention BEFORE DELETE ON dc_observations WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_change_events ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), event_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('delay','downsize','cancel','upsize','acceleration')), reason_code TEXT NOT NULL CHECK(reason_code IN ('power','financing','permit','supply_chain','demand_stated_by_operator','other_stated','unknown')), reason_quote TEXT, operator_stated INTEGER NOT NULL CHECK(operator_stated IN (0,1)), source_url TEXT NOT NULL, obs_ids TEXT NOT NULL CHECK(json_valid(obs_ids)), FOREIGN KEY(obs_id,project_id) REFERENCES dc_projects(obs_id,project_id) ON DELETE CASCADE, CHECK(reason_code='unknown' OR (operator_stated=1 AND length(trim(reason_quote))>0 AND reason_quote IS NOT NULL)), FOREIGN KEY(obs_id) REFERENCES dc_observations(obs_id) ON DELETE CASCADE );
CREATE INDEX dc_change_events_run ON dc_change_events(run_id);
CREATE TRIGGER dc_change_events_immutable BEFORE UPDATE ON dc_change_events BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_change_events_retention BEFORE DELETE ON dc_change_events WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_financing_events ( obs_id TEXT NOT NULL REFERENCES research_observations(observation_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), event_id TEXT PRIMARY KEY, project_id TEXT, entity_id TEXT, instrument TEXT NOT NULL CHECK(instrument IN ('loan','bond','equity','lease','subsidy')), amount_decimal TEXT, currency TEXT, maturity TEXT, collateral_text TEXT, admin_event_id TEXT, source_url TEXT NOT NULL, disclosed_vs_inferred TEXT NOT NULL CHECK(disclosed_vs_inferred='disclosed'), FOREIGN KEY(obs_id,project_id) REFERENCES dc_projects(obs_id,project_id) ON DELETE CASCADE, FOREIGN KEY(obs_id,entity_id) REFERENCES dc_entities(obs_id,entity_id) ON DELETE CASCADE, CHECK(project_id IS NOT NULL OR entity_id IS NOT NULL), CHECK((amount_decimal IS NULL)=(currency IS NULL)), FOREIGN KEY(obs_id) REFERENCES dc_observations(obs_id) ON DELETE CASCADE );
CREATE INDEX dc_financing_events_run ON dc_financing_events(run_id);
CREATE TRIGGER dc_financing_events_immutable BEFORE UPDATE ON dc_financing_events BEGIN SELECT RAISE(ABORT,'immutable_dc_record'); END;
CREATE TRIGGER dc_financing_events_retention BEFORE DELETE ON dc_financing_events WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TABLE dc_review_batches ( batch_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, item_count INTEGER NOT NULL CHECK(item_count BETWEEN 1 AND 20), decided_at TEXT, decision_summary TEXT CHECK(decision_summary IS NULL OR decision_summary='pending'), CHECK(decided_at IS NULL) );
CREATE TRIGGER dc_review_batches_immutable BEFORE UPDATE ON dc_review_batches BEGIN SELECT RAISE(ABORT,'immutable_dc_batch'); END;
CREATE TRIGGER dc_review_batches_no_delete BEFORE DELETE ON dc_review_batches BEGIN SELECT RAISE(ABORT,'immutable_dc_batch'); END;
CREATE TABLE dc_review_batch_items ( batch_id TEXT NOT NULL REFERENCES dc_review_batches(batch_id), item_number INTEGER NOT NULL CHECK(item_number BETWEEN 1 AND 20), obs_id TEXT NOT NULL REFERENCES dc_observations(obs_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), PRIMARY KEY(batch_id,item_number), UNIQUE(batch_id,obs_id) );
CREATE TABLE dc_observation_reviews ( review_order INTEGER PRIMARY KEY AUTOINCREMENT, review_id TEXT NOT NULL UNIQUE, batch_id TEXT NOT NULL, item_number INTEGER NOT NULL, obs_id TEXT NOT NULL REFERENCES dc_observations(obs_id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES research_runs(run_id), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected','hold')), reviewed_at TEXT NOT NULL, reviewed_by TEXT NOT NULL CHECK(reviewed_by='kaz'), FOREIGN KEY(batch_id,item_number) REFERENCES dc_review_batch_items(batch_id,item_number) ON DELETE CASCADE, UNIQUE(batch_id,item_number) );
CREATE INDEX dc_reviews_observation ON dc_observation_reviews(obs_id,reviewed_at,review_order);
CREATE TRIGGER dc_reviews_match BEFORE INSERT ON dc_observation_reviews WHEN NOT EXISTS(SELECT 1 FROM dc_review_batch_items i WHERE i.batch_id=NEW.batch_id AND i.item_number=NEW.item_number AND i.obs_id=NEW.obs_id AND i.run_id=NEW.run_id) BEGIN SELECT RAISE(ABORT,'dc_batch_item_mismatch'); END;
CREATE TRIGGER dc_review_batch_items_immutable BEFORE UPDATE ON dc_review_batch_items BEGIN SELECT RAISE(ABORT,'immutable_dc_review'); END;
CREATE TRIGGER dc_review_batch_items_retention BEFORE DELETE ON dc_review_batch_items WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TRIGGER dc_observation_reviews_immutable BEFORE UPDATE ON dc_observation_reviews BEGIN SELECT RAISE(ABORT,'immutable_dc_review'); END;
CREATE TRIGGER dc_observation_reviews_retention BEFORE DELETE ON dc_observation_reviews WHEN COALESCE((SELECT state FROM research_runs WHERE run_id=OLD.run_id),'') != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE TRIGGER dc_tracker_projection AFTER INSERT ON research_observations WHEN NEW.method_version='dc-tracker-v1' BEGIN INSERT INTO dc_entities(obs_id,run_id,entity_id,name_ja,corporate_number) SELECT NEW.observation_id,NEW.run_id,json_extract(NEW.domain_json,'$.entity.entity_id'),json_extract(NEW.domain_json,'$.entity.name_ja'),json_extract(NEW.domain_json,'$.entity.corporate_number') WHERE json_extract(NEW.domain_json,'$.entity') IS NOT NULL; INSERT INTO dc_projects(obs_id,run_id,project_id,name_ja,operator_entity_id,country,prefecture,tracked_since,tracking_status) SELECT NEW.observation_id,NEW.run_id,json_extract(NEW.domain_json,'$.project.project_id'),json_extract(NEW.domain_json,'$.project.name'),json_extract(NEW.domain_json,'$.project.operator_entity_id'),json_extract(NEW.domain_json,'$.project.country'),json_extract(NEW.domain_json,'$.project.prefecture'),json_extract(NEW.domain_json,'$.project.tracked_since'),json_extract(NEW.domain_json,'$.project.tracking_status'); INSERT INTO dc_sites(obs_id,run_id,site_id,project_id,name,region,location_evidence_ref) SELECT NEW.observation_id,NEW.run_id,json_extract(NEW.domain_json,'$.site.site_id'),json_extract(NEW.domain_json,'$.site.project_id'),json_extract(NEW.domain_json,'$.site.name'),json_extract(NEW.domain_json,'$.site.region'),json_extract(NEW.domain_json,'$.site.location_evidence_ref') WHERE json_extract(NEW.domain_json,'$.site') IS NOT NULL; INSERT INTO dc_phases(obs_id,run_id,phase_id,site_id,phase_label,status,planned_service_date,actual_service_date) SELECT NEW.observation_id,NEW.run_id,json_extract(NEW.domain_json,'$.phase.phase_id'),json_extract(NEW.domain_json,'$.phase.site_id'),json_extract(NEW.domain_json,'$.phase.phase_label'),json_extract(NEW.domain_json,'$.phase.status'),json_extract(NEW.domain_json,'$.phase.planned_service_date'),json_extract(NEW.domain_json,'$.phase.actual_service_date') WHERE json_extract(NEW.domain_json,'$.phase') IS NOT NULL; INSERT INTO dc_observations(obs_id,run_id,project_id,site_id,phase_id,field,scope,scope_id,value_text,value_decimal,unit,as_of_date,source_id,source_url,source_published_at,fetched_at,evidence_sha256,evidence_level,basis,source_quote,status,drafted_by) SELECT NEW.observation_id,NEW.run_id,json_extract(NEW.domain_json,'$.project.project_id'),json_extract(NEW.domain_json,'$.site.site_id'),json_extract(NEW.domain_json,'$.phase.phase_id'),json_extract(NEW.domain_json,'$.field'),json_extract(NEW.domain_json,'$.scope'),json_extract(NEW.domain_json,'$.scope_id'),json_extract(NEW.domain_json,'$.value_text'),json_extract(NEW.domain_json,'$.value_decimal'),json_extract(NEW.domain_json,'$.unit'),json_extract(NEW.domain_json,'$.as_of_date'),json_extract(NEW.domain_json,'$.evidence.source_id'),json_extract(NEW.domain_json,'$.evidence.source_url'),json_extract(NEW.domain_json,'$.evidence.published_at'),json_extract(NEW.domain_json,'$.evidence.observed_at'),json_extract(NEW.domain_json,'$.evidence_sha256'),json_extract(NEW.domain_json,'$.evidence_level'),json_extract(NEW.domain_json,'$.evidence.basis'),json_extract(NEW.domain_json,'$.source_quote'),json_extract(NEW.domain_json,'$.status'),json_extract(NEW.domain_json,'$.drafted_by'); INSERT INTO dc_change_events(obs_id,run_id,event_id,project_id,kind,reason_code,reason_quote,operator_stated,source_url,obs_ids) SELECT NEW.observation_id,NEW.run_id,NEW.observation_id||':change',json_extract(NEW.domain_json,'$.project.project_id'),json_extract(NEW.domain_json,'$.change.kind'),json_extract(NEW.domain_json,'$.change.reason_code'),json_extract(NEW.domain_json,'$.change.reason_quote'),json_extract(NEW.domain_json,'$.change.operator_stated'),json_extract(NEW.domain_json,'$.evidence.source_url'),json_array(NEW.observation_id) WHERE json_extract(NEW.domain_json,'$.change') IS NOT NULL; INSERT INTO dc_financing_events(obs_id,run_id,event_id,project_id,entity_id,instrument,amount_decimal,currency,maturity,collateral_text,admin_event_id,source_url,disclosed_vs_inferred) SELECT NEW.observation_id,NEW.run_id,NEW.observation_id||':financing',json_extract(NEW.domain_json,'$.financing.project_id'),json_extract(NEW.domain_json,'$.financing.entity_id'),json_extract(NEW.domain_json,'$.financing.instrument'),json_extract(NEW.domain_json,'$.financing.amount_decimal'),json_extract(NEW.domain_json,'$.financing.currency'),json_extract(NEW.domain_json,'$.financing.maturity'),json_extract(NEW.domain_json,'$.financing.collateral_text'),json_extract(NEW.domain_json,'$.financing.admin_event_id'),json_extract(NEW.domain_json,'$.evidence.source_url'),json_extract(NEW.domain_json,'$.financing.disclosed_vs_inferred') WHERE json_extract(NEW.domain_json,'$.financing') IS NOT NULL; END;

-- Reject direct cross-run inserts as well as application-level scope mismatches.
CREATE TRIGGER dc_entities_run_match BEFORE INSERT ON dc_entities WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_projects_run_match BEFORE INSERT ON dc_projects WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_sites_run_match BEFORE INSERT ON dc_sites WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_phases_run_match BEFORE INSERT ON dc_phases WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_observations_run_match BEFORE INSERT ON dc_observations WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_change_events_run_match BEFORE INSERT ON dc_change_events WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_financing_events_run_match BEFORE INSERT ON dc_financing_events WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_review_batch_items_run_match BEFORE INSERT ON dc_review_batch_items WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
CREATE TRIGGER dc_observation_reviews_run_match BEFORE INSERT ON dc_observation_reviews WHEN NOT EXISTS(SELECT 1 FROM research_observations o WHERE o.observation_id=NEW.obs_id AND o.run_id=NEW.run_id AND o.method_version='dc-tracker-v1') BEGIN SELECT RAISE(ABORT,'dc_run_mismatch'); END;
